<!-- ============ EMERGENCY ============ -->
<section id="emergency" class="py-24 md:py-32">
  <div class="max-w-6xl mx-auto px-6">
    <div class="grid md:grid-cols-2 gap-14 items-center">
      <div class="reveal">
        <img src="https://images.unsplash.com/photo-1576201836106-db1758fd1c97?auto=format&fit=crop&w=1000&q=80"
             alt="A vet gently examining a dog" loading="lazy"
             class="w-full h-[380px] object-cover rounded-[2rem] shadow-soft">
      </div>
      <div class="reveal">
        <p class="text-xs uppercase tracking-[0.2em] text-clay font-medium">A vet in your pocket</p>
        <h2 class="font-display text-4xl md:text-5xl font-semibold mt-3">Even when it can't wait</h2>
        <p class="text-dusk/70 mt-4 leading-relaxed">Stay calm and know what to do. Free, vet-approved first-aid guidance is always available — and when you need more, talk to a vet right away.</p>

        <div class="mt-8 space-y-5">
          <div class="flex gap-4">
            <span class="shrink-0 h-9 w-9 rounded-full bg-clay/10 text-clay flex items-center justify-center font-medium">1</span>
            <div><h3 class="font-display text-xl font-semibold">Know what to do</h3><p class="text-sm text-dusk/70 mt-1 leading-relaxed">Vet-approved first aid for poisoning, choking, seizures, heatstroke, bleeding and more — clear "do / don't / get to a vet if…" guidance that works offline.</p></div>
          </div>
          <div class="flex gap-4">
            <span class="shrink-0 h-9 w-9 rounded-full bg-clay/10 text-clay flex items-center justify-center font-medium">2</span>
            <div><h3 class="font-display text-xl font-semibold">Talk to a vet now</h3><p class="text-sm text-dusk/70 mt-1 leading-relaxed">One tap connects you to the first available vet by video or audio. Your payment is held and refunded if no vet connects.</p></div>
          </div>
          <div class="flex gap-4">
            <span class="shrink-0 h-9 w-9 rounded-full bg-clay/10 text-clay flex items-center justify-center font-medium">3</span>
            <div><h3 class="font-display text-xl font-semibold">Find a 24/7 clinic nearby</h3><p class="text-sm text-dusk/70 mt-1 leading-relaxed">When hands-on care is needed, we point you to nearby emergency clinics — directly or on a vet's referral.</p></div>
          </div>
        </div>

        <p class="text-xs text-dusk/55 mt-6 leading-relaxed border-l-2 border-clay/40 pl-4">
          First-aid tips are informational only and <strong>not a substitute for emergency veterinary care.</strong>
          In a life-threatening emergency, contact your nearest veterinary clinic immediately.
        </p>
      </div>
    </div>
  </div>
</section>

<!-- ============ FOR VETS ============ -->
<section id="vets" class="py-24 md:py-32 bg-ink text-cream">
